import{_ as r,C as d,o as c,c as l,a6 as a,E as t,j as s,a as i}from"./chunks/framework.5dd0l9Wo.js";const v=JSON.parse('{"title":"DOM-Based Vulnerabilities","description":"Sources, sinks, web messages, JSON.parse, open redirects, cookie manipulation, and DOM clobbering.","frontmatter":{"title":"DOM-Based Vulnerabilities","description":"Sources, sinks, web messages, JSON.parse, open redirects, cookie manipulation, and DOM clobbering."},"headers":[],"relativePath":"dom/index.md","filePath":"dom/index.md"}'),p={name:"dom/index.md"};function h(u,e,m,b,g,k){const o=d("LabGroup"),n=d("TopicComplete");return c(),l("div",null,[e[0]||(e[0]=a('<h1 id="dom-based-vulnerabilities" tabindex="-1">DOM-Based Vulnerabilities <a class="header-anchor" href="#dom-based-vulnerabilities" aria-label="Permalink to &quot;DOM-Based Vulnerabilities&quot;">​</a></h1><p class="wd-section-lede">DOM bugs happen entirely in the browser. The server can return a perfectly encoded page; client-side JavaScript then reads an attacker-controlled source and writes it to a sink that executes or navigates.</p><div class="wd-callout"><p><strong>The model.</strong> A <em>source</em> is where untrusted data enters JavaScript. A <em>sink</em> is an API that turns data into markup, code, a URL, or a cookie. The vulnerability is a reachable path from source to sink with no validation that matches the sink&#39;s grammar.</p></div><h2 id="sources-and-sinks" tabindex="-1">Sources and sinks <a class="header-anchor" href="#sources-and-sinks" aria-label="Permalink to &quot;Sources and sinks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Sink</th><th>Effect</th></tr></thead><tbody><tr><td><code>location.search</code>, <code>location.hash</code></td><td><code>innerHTML</code>, <code>document.write</code></td><td>HTML/JS execution</td></tr><tr><td><code>location.href</code></td><td><code>location = ...</code></td><td>open redirect, <code>javascript:</code> execution</td></tr><tr><td><code>window.name</code>, <code>postMessage</code></td><td><code>eval</code>, <code>Function</code>, <code>setTimeout(string)</code></td><td>code execution</td></tr><tr><td><code>document.referrer</code></td><td><code>innerHTML</code></td><td>reflected DOM XSS</td></tr><tr><td><code>document.cookie</code></td><td><code>innerHTML</code></td><td>cookie value becomes markup</td></tr><tr><td><code>localStorage</code></td><td>any sink</td><td>persistence</td></tr></tbody></table><details class="details custom-block"><summary>🔬 Under the Hood: why <code>innerHTML</code> does not run <code>&lt;script&gt;</code></summary><p>The HTML fragment parser marks script elements inserted via <code>innerHTML</code> as &quot;already started&quot;; they are created but never executed. Event-handler attributes are different: <code>&lt;img src=x onerror=...&gt;</code> creates an element, the load fails, and the handler runs. That is why DOM payloads are event-driven rather than <code>&lt;script&gt;</code>-driven.</p><p><code>document.write</code> during parsing is the exception: it feeds the main parser, so a <code>&lt;script&gt;</code> written synchronously can execute. <code>eval</code> and <code>Function</code> do not involve HTML at all; they compile strings as JavaScript.</p></details><h2 id="web-messages" tabindex="-1">Web messages <a class="header-anchor" href="#web-messages" aria-label="Permalink to &quot;Web messages&quot;">​</a></h2><p><code>postMessage</code> is the standard cross-origin messaging API. The receiver must check <code>event.origin</code> and validate the message shape. If it writes <code>event.data</code> into a sink without checking, any page that can frame or open the target can send a payload.</p>',8)),t(o,{ids:"dom-lab-dom-xss-using-web-messages, dom-lab-dom-xss-using-web-messages-and-a-javascript-url, dom-lab-dom-xss-using-web-messages-and-json-parse"}),e[1]||(e[1]=a('<details class="details custom-block"><summary>🔬 Under the Hood: <code>JSON.parse</code> is not a sanitiser</summary><p><code>JSON.parse</code> validates syntax, not semantics. A message such as:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;load-channel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;javascript:alert(1)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>is valid JSON; the resulting object&#39;s <code>url</code> is then assigned to an iframe <code>src</code>. The parser did its job; the sink still executes the scheme. Validation must happen on the parsed fields, against the allowed values for that field.</p></details><h2 id="open-redirection" tabindex="-1">Open redirection <a class="header-anchor" href="#open-redirection" aria-label="Permalink to &quot;Open redirection&quot;">​</a></h2><p>If a URL parameter flows into <code>location.href</code>, <code>location.assign</code>, or an anchor <code>href</code>, the attacker can redirect to another origin or use a <code>javascript:</code> URL. Open redirects are also a building block for OAuth token theft and SSRF allow-list bypasses.</p>',3)),t(o,{ids:"dom-lab-dom-open-redirection"}),e[2]||(e[2]=s("h2",{id:"cookie-manipulation",tabindex:"-1"},[i("Cookie manipulation "),s("a",{class:"header-anchor",href:"#cookie-manipulation","aria-label":'Permalink to "Cookie manipulation"'},"​")],-1)),e[3]||(e[3]=s("p",null,[i("A script that writes a URL parameter into "),s("code",null,"document.cookie"),i(" lets the attacker set arbitrary cookie values. If the application later reflects a cookie into the DOM, the chain becomes XSS; if it uses the cookie for routing or personalisation, it can poison the session.")],-1)),t(o,{ids:"dom-lab-dom-cookie-manipulation"}),e[4]||(e[4]=a('<h2 id="dom-clobbering" tabindex="-1">DOM clobbering <a class="header-anchor" href="#dom-clobbering" aria-label="Permalink to &quot;DOM clobbering&quot;">​</a></h2><p>HTML <code>id</code> and <code>name</code> attributes create global variables. If a script expects <code>window.config</code> to be an object but an injected element with <code>id=&quot;config&quot;</code> shadows it, the script may read attacker-controlled properties. Clobbering can also bypass HTML filters by making <code>document.getElementById</code> return an unexpected element.</p>',2)),t(o,{ids:"dom-lab-dom-xss-exploiting-dom-clobbering, dom-lab-dom-clobbering-attributes-to-bypass-html-filters"}),e[5]||(e[5]=a('<details class="details custom-block"><summary>⚙️ Engine Variations: named access and clobbering</summary><ul><li><code>window.foo</code> resolves to an element with <code>id=&quot;foo&quot;</code> or <code>name=&quot;foo&quot;</code> in modern browsers.</li><li>A form&#39;s <code>action</code> can be clobbered by an input named <code>action</code>, so <code>form.action</code> becomes an element, not a URL.</li><li><code>document.getElementById</code> is not affected by clobbering, but <code>document.foo</code> and bare <code>foo</code> are.</li><li>Multiple elements with the same <code>name</code> create an <code>HTMLCollection</code>, whose <code>toString()</code> is <code>[object HTMLCollection]</code> — useful for bypassing checks that expect a string.</li></ul><p>Clobbering is a JavaScript namespace collision caused by HTML.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Avoid dangerous sinks: use <code>textContent</code> and <code>setAttribute</code>, not <code>innerHTML</code>. Validate URLs by parsing them and allowing only <code>https:</code> to expected hosts. For <code>postMessage</code>, check <code>event.origin</code> against an exact allow-list and validate the message schema. Do not use <code>eval</code> or string timers. Treat DOM clobbering as a namespace problem: use local variables and explicit element lookups.</p></div>',2)),t(n,{"topic-id":"dom-based-vulnerabilities",label:"Mark DOM vulnerabilities complete"})])}const _=r(p,[["render",h]]);export{v as __pageData,_ as default};
